# %%
# __TITLE__, one of RandomBench's ten scoring tasks (PLAN.md 4.5b).
#
# Generated by `python -m randombench.build` from tasks/templates/score.py,
# with the stored replies in data/. Edit the template, not this file, and
# build again.
#
# It never prompts a model. Run with -m X, it parses X's stored replies,
# scores them, and returns the score with the half-width of its 95% interval
# (D19). It returns False for a model with no stored replies, such as the
# server's default model in a push's creation run (D12), and for a score of
# None, below 2 valid answers (3.4). False shows as FAIL, which an average of
# task scores leaves out (1.3).
import kaggle_benchmarks as kbench

# This task's score: its key in score_answers().
SCORE = "__SCORE__"

# %%
# Each model's stored replies, merged across its runs (D3, D13): every
# distinct raw reply, with how many times the model gave it. Scoring pools a
# model's answers (D17), so their order and prompts aren't needed. Failed
# calls have no reply and don't count (3.4). Keyed by llm.name (1.3).
STORED = __STORED__

# %%
# --- begin randombench/parsing.py ---
# --- end randombench/parsing.py ---

# %%
